import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"CDS Reef: Rados Gateway","description":"","frontmatter":{"title":"CDS Reef: Rados Gateway","date":"2022-04-14T00:00:00.000Z","updated":"2022-04-14T00:00:00.000Z","tags":["Ceph","Distributed Storage","RADOS Gateway","RGW","Scalability"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/CDS_Reef_-_Rados_Gateway.md","filePath":"posts/2022/CDS_Reef_-_Rados_Gateway.md","lastUpdated":1780459816000}'),r={name:"posts/2022/CDS_Reef_-_Rados_Gateway.md"};function o(s,l,n,p,u,d){return a(),e("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次会议主要讨论了Ceph分布式存储系统中RGW（RADOS Gateway）的多个高层次项目和进展，涉及新功能的开发、现有功能的优化、测试和性能提升等方面。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Zipper项目</strong></p><ul><li>动态加载存储库，支持外部项目集成。</li><li>独立模式，无需集群连接即可运行。</li><li>开发过滤层，实现数据缓存和其他中间层策略。</li></ul></li><li><p><strong>S3 Select</strong></p><ul><li>支持JSON格式对象的查询。</li><li>与AeroFlight进行集成，理解列式数据集和Flight SQL。</li></ul></li><li><p><strong>异步重构项目</strong></p><ul><li>减少线程数，提高性能。</li></ul></li><li><p><strong>可观测性和追踪</strong></p><ul><li>集成Jaeger，构建追踪原语。</li><li>探索基于Lua的条件追踪。</li></ul></li><li><p><strong>多站点（Multi-Site）项目</strong></p><ul><li>动态重分片，提高可扩展性。</li><li>改进同步公平性，优化同步过程。</li></ul></li><li><p><strong>工作负载测试</strong></p><ul><li>重写多站点测试，使用Golang或其他支持并发的语言。</li><li>使用MinIO Warp进行工作负载测试。</li></ul></li><li><p><strong>HTTP/3支持</strong></p><ul><li>在RGW中添加HTTP/3支持，实现更低的延迟和更好的性能。</li></ul></li><li><p><strong>同步信息提供者</strong></p><ul><li>抽象同步API，支持非RGW数据源。</li></ul></li><li><p><strong>功能弃用</strong></p><ul><li>讨论弃用OMAP日志的可能性。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续推进Zipper项目中的各项功能开发。</li><li>完成S3 Select的JSON支持和AeroFlight集成。</li><li>完成异步重构项目，减少线程数。</li><li>完善可观测性和追踪功能，特别是条件追踪的实现。</li><li>完成多站点项目的动态重分片和同步公平性改进。</li><li>探索使用Golang重写多站点测试，并使用MinIO Warp进行工作负载测试。</li><li>开始HTTP/3支持的初步研究。</li><li>继续推进同步信息提供者的工作。</li><li>考虑在Reef版本中弃用OMAP日志。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续开发和测试Zipper项目中的功能。</li><li>完成S3 Select的JSON支持和AeroFlight集成。</li><li>完成异步重构项目，减少线程数。</li><li>完善可观测性和追踪功能。</li><li>完成多站点项目的动态重分片和同步公平性改进。</li><li>探索使用Golang重写多站点测试，并使用MinIO Warp进行工作负载测试。</li><li>开始HTTP/3支持的初步研究。</li><li>继续推进同步信息提供者的工作。</li><li>考虑在Reef版本中弃用OMAP日志。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li>讨论了在ToothAlley环境中进行大规模测试的可能性。</li><li>讨论了在Ceph Messenger中添加QUIC支持的可能性。</li><li>讨论了Deprecating features，特别是OMAP日志的支持。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议在讨论了所有议题后结束，Casey计划将新内容添加到Trello的Backlog中，并鼓励大家继续参与后续的讨论和开发工作。</p>',13)])])}const c=i(r,[["render",o]]);export{_ as __pageData,c as default};
